#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(void) {
    pthread_attr_t attr; 
    int status;

    // 1. Initialize the attributes object with default values
    status = pthread_attr_init(&attr);
    if (status != 0) {
        fprintf(stderr, "Error initializing attributes (pthread_attr_init): %d\n", status);
        return EXIT_FAILURE;
    }
    printf("Attributes object initialized successfully.\n");

    // 2. Set a specific attribute (e.g., make future threads detached)
    status = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    if (status != 0) {
        fprintf(stderr, "Error setting detached state: %d\n", status);
        // Must still attempt to clean up initialized resources
        pthread_attr_destroy(&attr);
        return EXIT_FAILURE;
    }
    printf("Attribute (DETACHED state) set.\n");

    // The 'attr' object would normally be passed to pthread_create() here.

    // 3. Destroy the attributes object when it is no longer needed
    status = pthread_attr_destroy(&attr);
    if (status != 0) {
        fprintf(stderr, "Error destroying attributes (pthread_attr_destroy): %d\n", status);
        return EXIT_FAILURE;
    }
    printf("Attributes object successfully destroyed and resources released.\n");

    return EXIT_SUCCESS;
}
